  ('d10dde86-3916-47fd-a8fc-549b8cc8c0ba', 'd8a7704b-6ba2-4e7d-bc2d-fb2b2ce9dc75', 3,
   $$[{"domain": "Beeld- en geluidstechniek", "subdomain": "Informatieoverdracht"}]$$::jsonb,
   $$["staande golf", "knopen en buiken schetsen", "open en gesloten uiteinde", "grondtoon vergelijken"]$$::jsonb,
   $$Met een schets van knopen en buiken beoordelen of de grondtoon hoger of lager wordt als een uiteinde wordt gesloten.$$,
   $$natuurkunde-havo-2025-ii-muzikale-schelp-vraag3.png$$, 486,
   $$Leg uit met behulp van een schets met knopen (K) en buiken (B) of deze grondtoon hoger of lager is.$$, array['d48d04c1-b230-44e7-8e1a-73e681e4342b','73c6ac34-3450-4ecf-9a6f-2c8db810e68e']::uuid[]),
  ('b6b1b1eb-4fcd-46fa-8719-f4d455c4ec77', 'f6782296-66a6-4a79-96b7-5dab9866a1fb', 4,
   $$[{"domain": "Beweging en energie", "subdomain": "Kracht en beweging"}]$$::jsonb,
   $$["(s,t)-diagram", "vrije val met wrijving", "parachute", "diagram herkennen"]$$::jsonb,
   $$Het (s,t)-diagram herkennen dat past bij een vrije val gevolgd door een parachutesprong.$$,
   $$natuurkunde-havo-2025-ii-veilig-ontsnappen-vraag4.png$$, 454,
   $$Welk diagram komt het best overeen met het (s,t)-diagram van een basejump?

A diagram I
B diagram II
C diagram III
D diagram IV$$, array['7b44659f-e7ad-413b-b2a5-94e05a2bf8da']::uuid[]),
  ('5d46cdff-02c6-4c2d-95cf-fa3b4b4ada6a', 'f6782296-66a6-4a79-96b7-5dab9866a1fb', 5,
   $$[{"domain": "Beweging en energie", "subdomain": "Kracht en beweging"}]$$::jsonb,
